// Countdown ring — empties clockwise from 12 o'clock across the layer's duration.
// Transparent background. Arc length = 1 - iProgress.
uniform vec3  uColor;        // @param #FFFFFF
uniform float uThickness;    // @param 0.06 0.005 0.3
uniform float uRadius;       // @param 0.38 0.05 0.5
uniform float uTrackOpacity; // @param 0.15 0 1
uniform bool  uRoundCaps;    // @param true

const float TAU = 6.28318530718;

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float aa = 1.0 / iResolution.y;
  float r = uRadius;
  float hw = uThickness * 0.5;
  float len = length(p);

  // Full ring SDF (track)
  float dRing = abs(len - r) - hw;
  float track = 1.0 - smoothstep(-aa, aa, dRing);

  // Angle from top, clockwise, 0..1
  float f = fract(atan(p.x, p.y) / TAU + 1.0);
  float remain = clamp(1.0 - iProgress, 0.0, 1.0);

  float arc;
  if (uRoundCaps) {
    float dArc;
    if (f <= remain) {
      dArc = dRing;
    } else {
      vec2 e0 = vec2(0.0, r);
      float ea = remain * TAU;
      vec2 e1 = vec2(sin(ea), cos(ea)) * r;
      dArc = min(length(p - e0), length(p - e1)) - hw;
    }
    arc = 1.0 - smoothstep(-aa, aa, dArc);
  } else {
    float s = (f <= remain) ? min(f, remain - f) * TAU * len : -1.0;
    arc = track * clamp(s / aa + 0.5, 0.0, 1.0);
  }
  arc *= step(1e-4, remain);

  float a = max(arc, track * uTrackOpacity);
  fragColor = vec4(uColor, a);
}
